package com.thakur.employee.controller; import com.thakur.employee.dto.Requests.UserCreate;import com.thakur.employee.model.*;import com.thakur.employee.repository.UserRepository;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import java.util.*; @RestController @RequestMapping("/api/users") @RequiredArgsConstructor public class UserController {private final UserRepository repo;private final PasswordEncoder encoder;@GetMapping @PreAuthorize("hasRole('ADMIN')") List<AppUser> all(){return repo.findAll();}@PostMapping @PreAuthorize("hasRole('ADMIN')") AppUser create(@Valid @RequestBody UserCreate r){if(repo.existsByEmail(r.email()))throw new IllegalArgumentException("Email already exists");return repo.save(AppUser.builder().name(r.name()).email(r.email()).password(encoder.encode(r.password())).department(r.department()).role(Role.valueOf(r.role().toUpperCase())).build());}}
